-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الاستماع: استخلاص معلومة ودليل","passage":"في نص استماع مستقل يقرأه المعلم: زارت مجموعة من التلاميذ متحف البحرين الوطني، وشاهدوا أدوات قديمة واكتشفوا كيف يحفظ المتحف ذاكرة المجتمع. دوّن كل طالب معلومة أعجبته وسبب اختياره. يعتمد الفهم السمعي على تمييز الحدث الرئيس عن المشاهد الجزئية.","prompt":"ما الهدف الذي لاحظه الطلاب من زيارة المتحف؟","correct":"التعرف إلى التراث وحفظ الذاكرة","w1":"شراء معدات رياضية","w2":"تعلم السباحة","w3":"مسابقة ألعاب","practice":"استمع إلى خبر آخر من قراءة المعلم، ثم دوّن فكرته الرئيسية وتفصيلين صحيحين مع جملة تفسر أهمية كل تفصيل."},{"n":2,"skill":"فهم الانتماء والعطاء في نص أدبي","passage":"نموذج إثرائي أصلي: «يبقى أثر الإنسان بما يقدمه لمن حوله؛ فالمعلم يضيء طريق المعرفة، والمتطوع يساند المحتاج، والعامل المتقن يبني المكان». نستنتج أن تخليد الأثر يرتبط بقيمة العطاء، ولا ننسب هذه الأسطر إلى النص المعنون «موطن الخالدين».","prompt":"ما الفكرة المحورية للنموذج الإثرائي؟","correct":"خلود الأثر بالعمل النافع","w1":"الشهرة بلا إنجاز","w2":"تفضيل الراحة على العمل","w3":"إهمال الآخرين","practice":"اكتب فقرة عن شخصية خدمت مجتمعها، واذكر فعلًا محددًا يدل على أثرها، مع فصل الوقائع عن الرأي."},{"n":3,"skill":"التمييز: إزالة إبهام المعنى","passage":"في «اشتريتُ عشرين كتابًا» كلمة «كتابًا» تمييز مفرد منصوب يوضح المقصود من العدد عشرين. وفي «ازداد الطالب علمًا» كلمة «علمًا» تمييز منصوب يوضح نسبة الازدياد. نتعلم تحديد الكلمة المفسرة للغموض ولا نخلطها بالحال التي تصف الهيئة.","prompt":"ما إعراب «كتابًا» في «اشتريت عشرين كتابًا»؟","correct":"تمييز منصوب","w1":"فاعل مرفوع","w2":"حال منصوبة","w3":"مضاف إليه مجرور","practice":"اكتب ثلاثة أمثلة صحيحة للتمييز، وحدد المميَّز والتمييز واشرح ما الذي أوضحه في كل مثال."},{"n":4,"skill":"استنتاج الصورة الحسية في وصف البحر","passage":"نموذج إثرائي مستقل: «تمايلت الصواري عند الغروب، واشتدت الريح حول السفن، وسمع البحارة صفيرًا طويلًا بين الحبال». السمع والحركة يمنحان المشهد إحساسًا بالتوتر والعمل. لا تمثل هذه الجمل نص «أنين الصواري» ولا تعوض قراءته من مصدر مرخّص.","prompt":"أي حاسة يستهدفها وصف «صفير طويل بين الحبال»؟","correct":"السمع","w1":"التذوق","w2":"الشم","w3":"اللمس وحده","practice":"اكتب وصفًا من أربعة أسطر لميناء عند الغروب، مستخدمًا صورة سمعية وأخرى بصرية ثم فسر أثرهما."},{"n":5,"skill":"إجراء مقابلة صحفية محترمة","passage":"تبدأ المقابلة الصحفية بتحديد هدف واضح، وصياغة أسئلة مفتوحة ودقيقة، ثم الاستماع وتدوين الإجابات بموافقة الضيف. السؤال «كيف بدأت اهتمامك بالقراءة؟» يسمح بتفاصيل، بخلاف سؤال يفترض إجابة مسبقة. يراجع الكاتب الاقتباسات قبل نشرها.","prompt":"أي سؤال أكثر انفتاحًا في مقابلة مع كاتب؟","correct":"كيف بدأت كتابة القصص؟","w1":"أليست قصصك الأفضل دائمًا؟","w2":"هل تقول نعم فقط؟","w3":"أليس القراء مخطئين؟","practice":"أعد مقابلة مدرسية من خمس أسئلة مفتوحة مع مقدمة وخاتمة، وراجع نسبة الأقوال إلى أصحابها."},{"n":6,"skill":"تمييز الذكرى الشخصية من التعميم","passage":"نموذج أصلي مستقل: «تذكر سالم يوم احتفل زملاؤه بإنجازهم في المدرسة، فشكر معلمه وتحدث عن التعب الذي سبقه الفرح». تُبنى الذكرى السردية على زمان وموقف وشعور ودليل. لا نزعم أن هذا هو مضمون «ذكريات المطوع وبهجة التخرج» في المصدر.","prompt":"ما الذي يربط التعب بالفرح في النموذج؟","correct":"تحقيق إنجاز بعد جهد","w1":"ضياع الكتب","w2":"إغلاق المدرسة","w3":"توقف التعلم","practice":"اكتب ذكرى نجاح في ستة أسطر، موضحًا الحدث والزمان والشعور ودليلًا لغويًا عليه."},{"n":7,"skill":"النداء: أداة المنادى وإعرابه","passage":"في «يا خالدُ، اقرأْ» أداة النداء «يا»، والمنادى «خالدُ» علم مفرد مبني على الضم في محل نصب. أما «يا طالبَ العلمِ» فهو منادى مضاف منصوب. نميز بين نوعَي المنادى ولا نعمم حكم البناء على كل نداء.","prompt":"ما نوع «خالدُ» في جملة «يا خالدُ، اقرأ»؟","correct":"منادى علم مفرد مبني على الضم في محل نصب","w1":"مبتدأ مرفوع","w2":"تمييز منصوب","w3":"حال منصوبة","practice":"كوّن جملتي نداء، إحداهما لعلم مفرد والأخرى لمنادى مضاف، ثم أعرب المنادى في كل منهما."},{"n":8,"skill":"بناء مقطع وصفي يخدم الحدث","passage":"نموذج سردي أصلي: «دخلت مريم المكتبة بعد المطر. كانت النوافذ تلمع وقطرات الماء تنحدر خلف الزجاج، بينما علا صوت تقليب الصفحات». انتقل الوصف من المكان إلى الحركة فخدم المشهد، ويمكن تحسينه بحذف وصف لا علاقة له بالحدث.","prompt":"ما التفصيل الذي يدل على أثر المطر في المكان؟","correct":"قطرات الماء خلف الزجاج","w1":"عدد كراسي الحافلة","w2":"اسم متجر بعيد","w3":"موعد رحلة أخرى","practice":"اكتب قصة قصيرة تبدأ في مكان مفتوح وتنتهي في مكان مغلق، مع وصفين حسيين مرتبطين بتحول الحدث."},{"n":9,"skill":"تحديد الشخصية من الأفعال لا من العنوان","passage":"نص نموذجي مستقل: «حين ضل مسافر الطريق، أرشدته امرأة خبيرة بمسارات الصحراء إلى موضع الماء، ثم عادت إلى قافلتها». نستدل من فعل الإرشاد على الخبرة والمساعدة. هذا مثال من إنشاء ضاديوم ولا يصف أحداث نص «أميرة الصحراء» الرسمي.","prompt":"ما الذي يدل على خبرة المرأة في النموذج؟","correct":"إرشاد المسافر إلى موضع الماء","w1":"الابتعاد دون مساعدة","w2":"ترك الأدوات","w3":"نسيان الطريق","practice":"اكتب وصفًا لشخصية صحراوية من خلال ثلاثة أفعال تدل على صفاتها، ولا تكتف بذكر الصفات مباشرة."},{"n":10,"skill":"تحليل رواية الأيام بفصل الشاهد عن التخمين","passage":"لفهم الفصول 14 إلى 20 من رواية «الأيام»، دوّن الأحداث من نسخة النص المرخصة، وحدد أثر المكان في تجربة الراوي مدعمًا باستشهاد صحيح. نموذج مستقل للتدريب: «توقف الفتى أمام الدرج، ثم استمع إلى الخطوات حتى اهتدى إلى المدخل». نستدل من الأفعال على الاستعانة بالسمع، ولا ننسب الواقعة إلى الرواية.","prompt":"أي عبارة في النموذج تبين الاستعانة بالسمع؟","correct":"استمع إلى الخطوات","w1":"توقف أمام الدرج","w2":"الاهتداء إلى المدخل بلا سبب","w3":"وصف لون الجدار","practice":"اقرأ الفصل المحدد في نسختك، ثم سجل حدثًا موثقًا وشاهدًا، وافصل بين ما قاله النص وما استنتجته."},{"n":11,"skill":"مراجعة مهارات الفهم والنحو والتعبير","passage":"في مراجعة أصلية تجمع المهارات: «عاد الطالب مسرورًا، ثم قال: يا صديقي، لخص ما قرأناه في ثلاث جمل». نحدد «مسرورًا» حالًا، و«يا» أداة نداء، ونختار فكرة رئيسية ونحذف التفاصيل غير المؤثرة عند التلخيص. مراجعة المهارات لا تغني عن نصوص الكتاب.","prompt":"ما وظيفة كلمة «مسرورًا» في النموذج؟","correct":"حال تصف هيئة الطالب","w1":"منادى علم مفرد","w2":"تمييز عدد","w3":"مستثنى بإلا","practice":"اكتب ملخصًا من ثلاث جمل عن موقف مدرسي، وضع فيه نداءً وحالًا، ثم راجع دقة الإعراب والترابط."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='وطني هويتي' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF coalesce(trim(target_content),'')='' THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.',
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_G8_T1_NATIONAL_IDENTITY_11_20261008','notOfficialBook',true,'ocrReview','pending','options',jsonb_build_array(r.correct,r.w1,r.w2,r.w3)),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_G8_T1_NATIONAL_IDENTITY_11_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_G8_T1_NATIONAL_IDENTITY_11_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_G8_T1_NATIONAL_IDENTITY_11_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;